component.css:
.sb-root {
  width: 100%;
  max-width: 360px;
  margin: 6px auto;
  position: relative;
  aspect-ratio: 1086 / 1448;
  border-radius: 9px;
  overflow: hidden;
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  background: #ede3cf;
}

.sb-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.sb-data { display: none; }


.sb-box {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  color: #33291e;
}

.sb-timebox { left: 26.2%; top: 16.0%; width: 24.7%; height: 6.2%; }
.sb-locbox  { left: 52.5%; top: 16.0%; width: 27.8%; height: 6.2%; }
.sb-time, .sb-loc {
  font-family: Georgia, "Times New Roman", "Songti SC", "SimSun", serif;
  font-size: 10px;
  letter-spacing: 0.4px;
  white-space: nowrap;
  max-width: 96%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sb-time { font-weight: 700; }




.sb-stage {
  position: absolute;
  left: 19.5%;
  top: 27%;
  width: 63%;
  height: 40%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  text-align: center;
  color: #33291e;
}
.sb-line { animation: sbIn 0.34s ease both; }
.sb-line:nth-child(2) { animation-delay: 0.07s; }
.sb-line:nth-child(3) { animation-delay: 0.14s; }
.sb-line:nth-child(4) { animation-delay: 0.21s; }
@keyframes sbIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: none; }
}
.sb-back .sb-line { animation-name: sbBack; }
@keyframes sbBack {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: none; }
}

.sb-text {
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.sb-name {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--sc, #8b3a30);
  margin-bottom: 2px;
  opacity: 0.92;
}
.sb-name::before,
.sb-name::after {
  content: "·";
  opacity: 0.5;
  margin: 0 4px;
}
.sb-talk .sb-text {
  color: var(--sc, #8b3a30);
}
.sb-narr .sb-text {
  font-style: italic;
  color: #6b6156;
}


.sb-pager {
  position: absolute;
  left: 19.5%;
  width: 63%;
  top: 68.2%;
  height: 4.4%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
}
.sb-btn {
  width: 30px;
  height: 21px;
  border-radius: 999px;
  background: rgba(51, 41, 30, 0.08);
  border: 1px solid #33291e;
  color: #33291e;
  font-size: 9px;
  cursor: pointer;
  user-select: none;
  line-height: 1;
  transition: background 0.15s, transform 0.15s;
}
.sb-btn:hover:not(:disabled) { background: rgba(51, 41, 30, 0.2); }
.sb-btn:active:not(:disabled) { transform: scale(0.93); }
.sb-btn:disabled { opacity: 0.25; cursor: default; }
.sb-pageinfo {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 9px;
  color: #6b6156;
}
.sb-pageinfo b { color: #33291e; font-size: 10px; }



.sb-meter {
  position: absolute;
  left: 16.9%;
  width: 62.2%;
}
.sb-thirst { top: 74.7%; height: 8%; }
.sb-hunger { top: 84.8%; height: 7.7%; }

.sb-fill {
  position: absolute;
  left: 19.7%;
  top: 18%;
  bottom: 18%;
  width: 0;
  border-radius: 999px;
  background: #2b2620;
  transition: width 0.9s cubic-bezier(0.22, 0.9, 0.3, 1);
}
.sb-fill.sb-danger {
  background: #8b3a30;
  animation: sbPulse 1.6s ease-in-out infinite;
}
@keyframes sbPulse { 50% { opacity: 0.55; } }
